{"content": "1|// RFC 6455 WebSocket, hand-rolled on the raw socket node:http hands us from the
2|// 'upgrade' event. Pure, byte-level pieces (handshake, framing, masking) that
3|// the unit tests can drive with Buffers. Scope: small unfragmented frames only
4|// (this is a LAN game with tiny JSON messages), so no fragmentation/extensions.
5|import { createHash } from 'node:crypto';
6|
7|export const GUID = '258EAFA5-E914-47DA-95CA-C5AB0DC85B11';
8|export const OP = { text: 0x1, close: 0x8, ping: 0x9, pong: 0xa };
9|export const MAX_PAYLOAD = 65535; // frames above this are rejected (small frames only)
10|
11|// --- Handshake ---
12|
13|// RFC 6455 §4.2.2: base64(SHA-1(key + GUID)).
14|export function acceptKey(key) {
15|  return createHash('sha1').update(key + GUID).digest('base64');
16|}
17|
18|const KEY_RE = /^[A-Za-z0-9+/]{22}==$/; // base64 of the required 16 random bytes
19|
20|// Validate the headers of an upgrade request (node:http lowercases them).
21|// Returns { ok: true, key } or { ok: false, status, reason, extra }.
22|export function validateUpgrade(h) {
23|  if (!h || h.upgrade?.toLowerCase() !== 'websocket')
24|    return { ok: false, status: 400, reason: 'Bad Request' };
25|  const tokens = (h.connection ?? '').toLowerCase().split(',').map((s) => s.trim());
26|  if (!tokens.includes('upgrade'))
27|    return { ok: false, status: 400, reason: 'Bad Request' };
28|  if (h['sec-websocket-version'] !== '13')
29|    return { ok: false, status: 426, reason: 'Upgrade Required', extra: 'Sec-WebSocket-Version: 13\r\n' };
30|  const key = h['sec-websocket-key'];
31|  if (typeof key !== 'string' || !KEY_RE.test(key))
32|    return { ok: false, status: 400, reason: 'Bad Request' };
33|  return { ok: true, key };
34|}
35|
36|// The full 101 reply that switches the HTTP connection into WebSocket mode.
37|export function handshakeResponse(key) {
38|  return `HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: ${acceptKey(key)}\r\n\r\n`;
39|}
40|
41|// --- Framing ---
42|
43|// XOR the payload with the 4 mask bytes, in place (symmetric: mask twice = original).
44|export function applyMask(data, mask) {
45|  for (let i = 0; i < data.length; i++) data[i] ^= mask[i & 3];
46|  return data;
47|}
48|
49|// Encode one unmasked server frame (server frames are never masked, RFC §5.1).
50|export function encodeFrame(opcode, payload = '') {
51|  const data = typeof payload === 'string' ? Buffer.from(payload, 'utf8') : Buffer.from(payload);
52|  if (data.length > MAX_PAYLOAD) throw new Error('ws: frame too large');
53|  if (opcode > 7 && data.length > 125) throw new Error('ws: control frame payload > 125');
54|  const head = data.length < 126 ? Buffer.from([0x80 | opcode, data.length]) : Buffer.alloc(4);
55|  if (head.length === 4) { // 126..65535 bytes: 16-bit extended length
56|    head[0] = 0x80 | opcode; head[1] = 126; head.writeUInt16BE(data.length, 2);
57|  }
58|  return Buffer.concat([head, data]);
59|}
60|
61|const KNOWN_OPCODES = new Set([0x1, 0x2, 0x8, 0x9, 0xa]);
62|
63|// Try to decode ONE frame from the front of `buf`. Returns null while more bytes
64|// are needed; otherwise { fin, opcode, masked, payload, bytes } with the payload
65|// unmasked and copied (the caller keeps `buf`) and `bytes` = total frame size.
66|// Throws on protocol violations (reserved bits, fragments, oversized control frames).
67|export function decodeFrame(buf) {
68|  if (buf.length < 2) return null;
69|  const fin = (buf[0] & 0x80) !== 0, rsv = buf[0] & 0x70, opcode = buf[0] & 0x0f;
70|  const masked = (buf[1] & 0x80) !== 0;
71|  let len = buf[1] & 0x7f, off = 2;
72|  if (rsv !== 0) throw new Error('ws: reserved bits set');
73|  if (!KNOWN_OPCODES.has(opcode)) throw new Error('ws: reserved opcode');
74|  if (!fin) throw new Error('ws: fragmented frames not supported');
75|  if (len === 127) throw new Error('ws: 64-bit frame lengths not supported');
76|  if (len === 126) {
77|    if (buf.length < 4) return null;
78|    len = buf.readUInt16BE(2); off = 4;
79|  }
80|  if (opcode > 7 && len > 125) throw new Error('ws: control frame payload > 125');
81|  if (masked && buf.length < off + 4) return null;
82|  const mask = masked ? buf.subarray(off, off + 4) : null;
83|  if (masked) off += 4;
84|  if (buf.length < off + len) return null;
85|  const payload = Buffer.from(buf.subarray(off, off + len));
86|  if (mask) applyMask(payload, mask);
87|  return { fin, opcode, masked, payload, bytes: off + len };
88|}
89|
90|// Incremental reader for a stream: pass it arbitrary chunks, it emits complete
91|// frames via `onFrame` in arrival order and lets protocol errors propagate.
92|export function createFrameReader(onFrame) {
93|  let buf = null;
94|  return (chunk) => {
95|    buf = buf ? Buffer.concat([buf, chunk]) : Buffer.from(chunk);
96|    for (;;) {
97|      if (!buf) return;
98|      const f = decodeFrame(buf);
99|      if (!f) return;
100|      buf = f.bytes < buf.length ? buf.subarray(f.bytes) : null;
101|      onFrame(f);
102|    }
103|  };
104|}
105|
106|// --- Connection: one live WebSocket over an upgraded socket ---
107|
108|// 2-byte close code + optional utf8 reason (control payload limit: 125 bytes).
109|function closePayload(code, reason) {
110|  const r = Buffer.from(String(reason ?? ''), 'utf8').subarray(0, 123);
111|  return Buffer.concat([Buffer.from([code >> 8, code & 0xff]), r]);
112|}
113|
114|// Validate the upgrade, write the 101 reply, wrap the socket. Returns a
115|// WsConnection, or null after answering + closing an invalid handshake.
116|// (socket.end, never destroy-after-write: destroy discards unflushed bytes.)
117|export function acceptConnection(socket, headers) {
118|  const v = validateUpgrade(headers);
119|  if (!v.ok) {
120|    socket.on('error', () => {});
121|    socket.end(`HTTP/1.1 ${v.status} ${v.reason}\r\n${v.extra ?? ''}Connection: close\r\nContent-Length: 0\r\n\r\n`);
122|    return null;
123|  }
124|  socket.write(handshakeResponse(v.key));
125|  return new WsConnection(socket);
126|}
127|
128|export class WsConnection {
129|  // Text frames come out as onMessage(string); pings are answered with pongs
130|  // automatically; a close from either side ends the socket and fires onClose
131|  // exactly once. Binary frames are refused (the protocol is JSON text only).
132|  constructor(socket) {
133|    this.socket = socket;
134|    this.onMessage = null;
135|    this.onClose = null;
136|    this.open = true;
137|    this.closing = false;
138|    socket.setNoDelay(true); // latency matters more than bandwidth here
139|    const reader = createFrameReader((f) => this._onFrame(f));
140|    socket.on('data', (chunk) => { try { reader(chunk); } catch { this._close(1002, 'protocol error'); } });
141|    socket.on('error', () => {}); // socket errors surface as 'close', never a crash
142|    socket.on('close', () => this._closed());
143|  }
144|
145|  send(text) { this._send(OP.text, Buffer.from(String(text), 'utf8')); }
146|  close(code = 1000, reason = '') { this._close(code, reason); }
147|
148|  _onFrame(f) {
149|    if (f.opcode === OP.ping) return this._send(OP.pong, f.payload);
150|    if (f.opcode === OP.pong) return; // RTT is measured with app-level ping/pong messages
151|    if (f.opcode === OP.close) {
152|      const code = f.payload.length >= 2 ? f.payload.readUInt16BE(0) : 1000;
153|      return this._close(code, ''); // echo the close, then end
154|    }
155|    if (f.opcode === OP.text) return this.onMessage?.(f.payload.toString('utf8'));
156|    this._close(1003, 'binary not supported');
157|  }
158|
159|  _send(opcode, payload) {
160|    if (this.closing) return;
161|    try { this.socket.write(encodeFrame(opcode, payload)); } catch { /* socket died mid-write */ }
162|  }
163|
164|  // Send a close frame, then end the socket (end flushes; destroy would not).
165|  _close(code, reason) {
166|    if (this.closing) return;
167|    this._send(OP.close, closePayload(code, reason));
168|    this.closing = true;
169|    this.socket.end();
170|  }
171|
172|  _closed() {
173|    if (!this.open) return;
174|    this.open = false;
175|    this.onClose?.();
176|  }
177|}", "total_lines": 177, "file_size": 7577, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|// The multiplayer message language: one entry per message type, declaring its
2|// direction ('cs' client → server, 'sc' server → client), its wire fields and
3|// its design rate. One shared encode/decode pair is driven by those entries,
4|// so every packet is validated against the same definitions that produce the
5|// protocol table in NOTES.md (`node tools/protocol-table.mjs`).
6|//
7|// Wire format: JSON text frames tagged with `type` — messages are tiny and the
8|// intranet is fast, so readable beats compact. All times are milliseconds in
9|// the shared server clock (clients learn their offset via ping/pong, because
10|// the browser's WebSocket API hides the protocol-level ping/pong from JS).
11|
12|export const STAGES = ['lobby', 'countdown', 'racing', 'finished', 'ceremony'];
13|export const MAX_PLAYERS = 4;
14|
15|const err = (where, why) => new Error(`protocol: ${where} ${why}`);
16|
17|// --- Field validators (used by encode AND decode, so both sides agree) ---
18|
19|function str(v, w) {
20|  if (typeof v !== 'string' || v.length < 1 || v.length > 24) throw err(w, 'must be a 1..24 char string');
21|  return v;
22|}
23|function num(v, w) {
24|  if (typeof v !== 'number' || !Number.isFinite(v)) throw err(w, 'must be a finite number');
25|  return v;
26|}
27|function idNum(v, w) {
28|  if (!Number.isInteger(v) || v < 1) throw err(w, 'must be a positive integer');
29|  return v;
30|}
31|function seedNum(v, w) {
32|  if (!Number.isInteger(v) || v < 0) throw err(w, 'must be a non-negative integer');
33|  return v;
34|}
35|function stageOf(v, w) {
36|  if (!STAGES.includes(v)) throw err(w, `must be one of ${STAGES.join('|')}`);
37|  return v;
38|}
39|function rosterOf(v, w) {
40|  if (!Array.isArray(v) || v.length > MAX_PLAYERS) throw err(w, `must be an array of at most ${MAX_PLAYERS} players`);
41|  return v.map((p, i) => {
42|    if (typeof p !== 'object' || p === null || Array.isArray(p)) throw err(`${w}[${i}]`, 'must be an object');
43|    for (const k of Object.keys(p)) if (k !== 'id' && k !== 'name') throw err(`${w}[${i}]`, `has unknown field ${k}`);
44|    if (!('id' in p) || !('name' in p)) throw err(`${w}[${i}]`, 'needs id and name');
45|    return { id: idNum(p.id, `${w}[${i}].id`), name: str(p.name, `${w}[${i}].name`) };
46|  });
47|}
48|
49|const tOrNull = (v, w) => (v === null ? null : num(v, w));
50|// A jump-start penalty: milliseconds the server added to a finisher's time, or
51|// null on a DNF row (no crossing time, nothing to penalise).
52|const penOf = (v, w) => {
53|  if (v === null) return null;
54|  if (typeof v !== 'number' || !Number.isFinite(v) || v < 0) throw err(w, 'must be a non-negative number or null');
55|  return v;
56|};
57|const boolOf = (v, w) => {
58|  if (typeof v !== 'boolean') throw err(w, 'must be a boolean');
59|  return v;
60|};
61|// One results-table row for the settled race: finished players first in
62|// official order (time + penalty, then earliest report), DNFs last with
63|// t = null and pen = null.
64|const resultsOf = (v, w) => {
65|  if (!Array.isArray(v) || v.length > MAX_PLAYERS) throw err(w, `must be an array of at most ${MAX_PLAYERS} players`);
66|  return v.map((r, i) => {
67|    if (typeof r !== 'object' || r === null || Array.isArray(r)) throw err(`${w}[${i}]`, 'must be an object');
68|    for (const k of Object.keys(r)) if (k !== 'id' && k !== 'name' && k !== 't' && k !== 'dnf' && k !== 'pen') throw err(`${w}[${i}]`, `has unknown field ${k}`);
69|    if (!('id' in r) || !('name' in r) || !('t' in r) || !('dnf' in r) || !('pen' in r)) throw err(`${w}[${i}]`, 'needs id, name, t, dnf and pen');
70|    return {
71|      id: idNum(r.id, `${w}[${i}].id`),
72|      name: str(r.name, `${w}[${i}].name`),
73|      t: tOrNull(r.t, `${w}[${i}].t`),
74|      dnf: boolOf(r.dnf, `${w}[${i}].dnf`),
75|      pen: penOf(r.pen, `${w}[${i}].pen`),
76|    };
77|  });
78|};
79|
80|// --- The registry ---
81|
82|export const MESSAGES = {
83|  // client → server
84|  join:       { dir: 'cs', rate: 'once, on entering the lobby', fields: { name: str } },
85|  name:       { dir: 'cs', rate: 'on change, in lobby',          fields: { name: str } },
86|  start:      { dir: 'cs', rate: 'user-triggered',               fields: {} },
87|  pos:        { dir: 'cs', rate: '15 Hz while racing',           fields: { x: num, z: num, h: num, s: num } },
88|  finish:     { dir: 'cs', rate: 'once per race',                fields: { t: num } },
89|  jump:       { dir: 'cs', rate: 'user-triggered, before green', fields: {} },
90|  again:      { dir: 'cs', rate: 'user-triggered, in ceremony',  fields: {} },
91|  ping:       { dir: 'cs', rate: 'about 1 Hz while syncing',     fields: { t: num } },
92|  // server → client
93|  roster:     { dir: 'sc', rate: 'on change',                    fields: { players: rosterOf, seed: seedNum } },
94|  countdown:  { dir: 'sc', rate: 'once per race',                fields: { goAt: num } },
95|  go:         { dir: 'sc', rate: 'once per race',                fields: { goAt: num } },
96|  posRelay:   { dir: 'sc', rate: 'per player, 15 Hz',            fields: { id: idNum, x: num, z: num, h: num, s: num } },
97|  stage:      { dir: 'sc', rate: 'on change',                    fields: { stage: stageOf } },
98|  disconnect: { dir: 'sc', rate: 'on player leaving',            fields: { id: idNum } },
99|  pong:       { dir: 'sc', rate: 'on ping',                      fields: { t: num, s: num } },
100|  finishInfo: { dir: 'sc', rate: 'per finisher, once',           fields: { id: idNum, t: num } },
101|  jumped:     { dir: 'sc', rate: 'per jump, once',              fields: { id: idNum, pen: num } },
102|  results:    { dir: 'sc', rate: 'once, when the race is settled', fields: { players: resultsOf } },
103|};
104|
105|// --- The encode/decode pair ---
106|
107|// encode(type, data) → JSON string, fields validated on the way out.
108|export function encode(type, data) {
109|  const def = MESSAGES[type];
110|  if (!def) throw err(type, 'is not a known message type');
111|  const out = { type };
112|  for (const [f, check] of Object.entries(def.fields)) out[f] = check(data?.[f], `${type}.${f}`);
113|  return JSON.stringify(out);
114|}
115|
116|// decode(text) → { type, data }, or throws on anything unknown or malformed:
117|// bad JSON, non-objects, unknown types, missing/unknown fields, wrong value types.
118|export function decode(text) {
119|  let m = null;
120|  try { m = JSON.parse(text); } catch { /* handled below */ }
121|  if (typeof m !== 'object' || m === null || Array.isArray(m)) throw err('packet', 'must be a JSON object');
122|  const def = MESSAGES[m.type];
123|  if (!def) throw err('packet', `unknown message type ${JSON.stringify(m.type)}`);
124|  const known = Object.keys(def.fields);
125|  for (const k of Object.keys(m)) if (k !== 'type' && !known.includes(k)) throw err(m.type, `unknown field ${k}`);
126|  const data = {};
127|  for (const [f, check] of Object.entries(def.fields)) data[f] = check(m[f], `${m.type}.${f}`);
128|  return { type: m.type, data };
129|}
130|
131|// Markdown table of the whole protocol, generated from the registry. NOTES.md
132|// embeds it between markers; a test keeps the two from drifting apart.
133|export function protocolTable() {
134|  const rows = Object.entries(MESSAGES).map(([name, d]) =>
135|    `| ${name} | ${d.dir === 'cs' ? 'client → server' : 'server → client'} | ${Object.keys(d.fields).join(' ') || '—'} | ${d.rate} |`);
136|  return ['| type | from | fields | rate |', '|---|---|---|---|', ...rows].join('\n');
137|}", "total_lines": 137, "file_size": 7143, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|// FairFahren game server: serves the static game exactly like `npm start`, and
2|// speaks WebSocket on /ws — the race rules (raceState.js) are wired onto every
3|// accepted connection below. Usage: node server/main.mjs [--seed N] [port]
4|import { createServer } from 'node:http';
5|import { resolve } from 'node:path';
6|import { fileURLToPath } from 'node:url';
7|import { serveStatic } from './static.mjs';
8|import { acceptConnection } from './ws.js';
9|import { createRaceState } from './raceState.js';
10|import { encode } from './protocol.js';
11|import { DEFAULT_CITY } from '../src/world/cityGen.js';
12|
13|const ROOT = resolve(fileURLToPath(new URL('..', import.meta.url)));
14|
15|// Composes the game server. `onConnect(conn)` receives every accepted
16|// WebSocket connection: { send(text), close(code, reason), onMessage(cb), onClose(cb) }.
17|export function createGameServer({ onConnect } = {}) {
18|  const server = createServer(serveStatic(ROOT));
19|  const connections = new Set();
20|  server.on('upgrade', (req, socket) => {
21|    if (new URL(req.url, 'http://x').pathname !== '/ws') return socket.destroy();
22|    const conn = acceptConnection(socket, req.headers);
23|    if (!conn) return; // invalid handshake: already answered and destroyed
24|    connections.add(conn);
25|    onConnect?.(conn); // sets conn.onMessage / conn.onClose as it sees fit
26|    // Keep our set tidy whatever the caller did: run our cleanup after theirs.
27|    const callerClose = conn.onClose;
28|    conn.onClose = () => {
29|      connections.delete(conn);
30|      callerClose?.();
31|    };
32|  });
33|  return { server, connections };
34|}
35|
36|if (import.meta.main) {
37|  // Usage: node server/main.mjs [--seed N] [port]. Flag and positional port
38|  // are parsed apart, in either order; SEED env also works.
39|  const argv = process.argv.slice(2);
40|  const seedIx = argv.indexOf('--seed');
41|  const seed = seedIx === -1
42|    ? (process.env.SEED !== '' && Number.isInteger(Number(process.env.SEED)) ? Number(process.env.SEED) : DEFAULT_CITY.seed)
43|    : Number(argv[seedIx + 1]);
44|  if (!Number.isInteger(seed) || seed < 0) {
45|    console.error(`Usage: node server/main.mjs [--seed <non-negative integer>] [port]  (got "--seed ${argv[seedIx + 1]}")`);
46|    process.exit(1);
47|  }
48|  const PORT = Number(argv.filter((a, i) => i !== seedIx && (i !== seedIx + 1 || seedIx === -1))[0] ?? process.env.PORT ?? 8080);
49|  // The server owns the rules and the seed; clients regenerate the same city
50|  // from it (phase 3). Rules are pure (raceState.js) and get everything from
51|  // here injected, so tests drive them over FakeNet instead of sockets.
52|  const race = createRaceState({
53|    seed,
54|    now: () => Date.now(),
55|    send: (conn, type, data) => conn.send(encode(type, data)),
56|    close: (conn, code, reason) => conn.close(code, reason),
57|    schedule: (delayMs, fn) => setTimeout(fn, delayMs), // real timers; tests swap in FakeNet.schedule
58|  });
59|  // 0.0.0.0: reachable from other machines on the intranet, not just localhost.
60|  createGameServer({
61|    onConnect: (conn) => {
62|      race.connect(conn);
63|      conn.onMessage = (text) => race.onMessage(conn, text);
64|      conn.onClose = () => race.disconnect(conn);
65|    },
66|  }).server.listen(PORT, '0.0.0.0', () =>
67|    console.log(`FairFahren server on http://0.0.0.0:${PORT} (game + WebSocket /ws, race seed ${seed})`));
68|}", "total_lines": 68, "file_size": 3280, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|// In-memory stand-in for the real network: FakeServer hands out FakeConnection
2|// pairs (server side ↔ client side) whose messages are delivered straight to
3|// the peer's handler — immediately, after N ms on FakeNet's virtual clock, or
4|// never (drop). Race logic (phase 2) is driven end-to-end through these pairs
5|// with deterministic timestamps: no sockets, no real timers.
6|//
7|// The connection shape mirrors the real WsConnection from ws.js:
8|// send(text), close(), onMessage(cb), onClose(cb), plus a server-assigned id.
9|
10|// Virtual clock + FIFO event queue. advance(ms) runs everything that became
11|// due, in schedule order; handlers may schedule follow-ups mid-advance.
12|export class FakeNet {
13|  constructor(start = 0) {
14|    this.now = start;
15|    this.queue = []; // { at, seq, fn }, kept sorted by (at, seq)
16|    this._seq = 0;
17|  }
18|
19|  schedule(delay, fn) {
20|    this.queue.push({ at: this.now + Math.max(0, delay), seq: this._seq++, fn });
21|    this.queue.sort((a, b) => a.at - b.at || a.seq - b.seq);
22|  }
23|
24|  advance(ms) {
25|    const end = this.now + ms;
26|    while (this.queue.length && this.queue[0].at <= end) {
27|      this.now = this.queue[0].at;
28|      this.queue.shift().fn();
29|    }
30|    this.now = end;
31|  }
32|}
33|
34|const resolve = (v) => (typeof v === 'function' ? v() : v);
35|
36|// One end of a wire pair. opts: { latency = 0, drop = false } — plain values or
37|// functions, re-read on every send, so tests can inject jitter or selective loss.
38|export class FakeConnection {
39|  constructor(net, opts = {}) {
40|    this.net = net;
41|    this.opts = opts;
42|    this.id = 0;
43|    this.peer = null;
44|    this.onMessage = null;
45|    this.onClose = null;
46|    this.closed = false;
47|  }
48|
49|  send(text) {
50|    if (this.closed || resolve(this.opts.drop)) return;
51|    const peer = this.peer;
52|    const deliver = () => !peer.closed && peer.onMessage?.(text);
53|    const delay = resolve(this.opts.latency ?? 0);
54|    if (delay > 0) this.net.schedule(delay, deliver); else deliver();
55|  }
56|
57|  // Clean disconnect: the closer learns at once, the peer after the wire delay.
58|  // `code`/`reason` are ignored for delivery but recorded, so tests can verify
59|  // reject messages (the real WsConnection sends them in a close frame).
60|  close(code, reason) {
61|    if (this.closed) return;
62|    this.closed = true;
63|    this.closedWith = { code, reason };
64|    this.onClose?.();
65|    const peer = this.peer;
66|    const notify = () => peer._peerClosed();
67|    const delay = resolve(this.opts.latency ?? 0);
68|    if (delay > 0) this.net.schedule(delay, notify); else notify();
69|  }
70|
71|  _peerClosed() {
72|    if (this.closed) return;
73|    this.closed = true;
74|    this.onClose?.();
75|  }
76|}
77|
78|// Creates the pairs: every connect() makes a server-side connection (handed to
79|// onConnect, with a fresh id) and returns the matching client side.
80|export class FakeServer {
81|  constructor(net) {
82|    this.net = net;
83|    this.onConnect = null;
84|    this._nextId = 1;
85|  }
86|
87|  // Both directions share clientOpts unless serverOpts is given explicitly.
88|  connect(clientOpts = {}, serverOpts = clientOpts) {
89|    const serverConn = new FakeConnection(this.net, serverOpts);
90|    const clientConn = new FakeConnection(this.net, clientOpts);
91|    serverConn.peer = clientConn;
92|    clientConn.peer = serverConn;
93|    serverConn.id = this._nextId++;
94|    this.onConnect?.(serverConn);
95|    return clientConn;
96|  }
97|}", "total_lines": 97, "file_size": 3332, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|// Static file serving, shared by the dev server (tools/serve.mjs) and the game
2|// server (server/main.mjs) — one implementation, no copy-paste. Extracted from
3|// tools/serve.mjs; the try/catch around path parsing is new: a malformed URL
4|// (e.g. "/%") must answer 400, not crash the process with an unhandled throw.
5|import { readFile } from 'node:fs/promises';
6|import { extname, join, normalize, sep } from 'node:path';
7|
8|const TYPES = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.mjs': 'text/javascript; charset=utf-8', '.css': 'text/css', '.json': 'application/json', '.md': 'text/markdown; charset=utf-8' };
9|
10|// Returns an http request listener that serves files from `root` on disk.
11|export function serveStatic(root) {
12|  return async (req, res) => {
13|    let path;
14|    try {
15|      path = decodeURIComponent(new URL(req.url, 'http://x').pathname);
16|    } catch {
17|      return res.writeHead(400).end();
18|    }
19|    const file = normalize(join(root, path === '/' ? 'index.html' : path));
20|    if (!file.startsWith(root + sep)) return res.writeHead(403).end(); // path traversal
21|    try {
22|      const body = await readFile(file);
23|      res.writeHead(200, { 'content-type': TYPES[extname(file)] ?? 'application/octet-stream', 'cache-control': 'no-store' });
24|      res.end(body);
25|    } catch {
26|      res.writeHead(404).end('Not found');
27|    }
28|  };
29|}", "total_lines": 29, "file_size": 1382, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

