{"content": "1|/**
2| * The online client core: connection + lobby flow, one source of race state
3| * for the UI. PURE: the transport (`conn`: send/onMessage/onClose), the clock
4| * (`now`) and the interval helper (`every` → cancel fn) are all injected, so
5| * tests drive whole lobbies over FakeNet on a virtual clock and the browser
6| * wires them to a real WebSocket. `on` is a plain callbacks object.
7| *
8| * Wire messages are JSON text frames, encoded/decoded by server/protocol.js
9| * (plain ES module, browser-safe). Malformed or unknown frames are dropped
10| * silently, exactly like raceState drops its garbage. Counts toward the size
11| * budget — kept tight.
12| */
13|import { decode, encode } from '../../server/protocol.js';
14|import { createClock } from './clock.js';
15|
16|// Close codes the server uses to reject a join (see NOTES.md): a fifth player
17|// in a full lobby (4000), a connection arriving mid-race (4001).
18|const TURNED_AWAY = new Set([4000, 4001]);
19|
20|export function createNetClient({ conn, name, now, every, on }) {
21|  const clock = createClock();
22|  let stage = 'connecting'; // lobby state arrives with the first message
23|  let players = []; // last roster
24|  let seed = null;
25|  let seenSeed = null; // guard so seedChange fires exactly once per distinct seed
26|  let goAt = null; // shared start moment from countdown/go
27|  let finishSent = false; // finishing is once per race
28|  let closed = false;
29|
30|  // ~1 Hz application ping keeps the master clock synced: the pong's echoed
31|  // `t` and server stamp `s`, read with the injected receive time, form one
32|  // min-rtt sample in the clock.
33|  every(1000, () => { if (!closed) conn.send(encode('ping', { t: now() })); });
34|
35|  conn.onMessage = (text) => {
36|    let m = null;
37|    try { m = decode(text); } catch { return; } // malformed/unknown: drop silently
38|    const d = m.data;
39|    switch (m.type) {
40|      case 'roster': // every roster message replaces the local roster
41|        players = d.players;
42|        seed = d.seed;
43|        if (stage === 'connecting') stage = 'lobby'; // a roster IS the lobby: joined and accepted
44|        on.roster?.(players, seed);
45|        if (seed !== seenSeed) { seenSeed = seed; on.seedChange?.(seed); } // rebuild city+mesh
46|        break;
47|      case 'stage':
48|        stage = d.stage;
49|        if (stage === 'countdown') finishSent = false; // a rematch race must report again
50|        on.stage?.(stage);
51|        break;
52|      case 'countdown':
53|      case 'go':
54|        goAt = d.goAt;
55|        on.goAt?.(goAt);
56|        break;
57|      case 'posRelay': // stamped with our receive time for the interp buffer
58|        on.peerPos?.({ id: d.id, t: now(), x: d.x, z: d.z, h: d.h, s: d.s });
59|        break;
60|      case 'disconnect':
61|        on.peerGone?.(d.id);
62|        break;
63|      case 'pong':
64|        clock.onPong(d.t, d.s, now());
65|        break;
66|      case 'finishInfo':
67|        on.finishInfo?.({ id: d.id, t: d.t });
68|        break;
69|      case 'jumped': // phase 4: someone moved before green; the server fixed the penalty
70|        on.jumped?.({ id: d.id, pen: d.pen });
71|        break;
72|      case 'results':
73|        on.results?.(d.players);
74|        break;
75|    }
76|  };
77|
78|  conn.onClose = (code, reason) => {
79|    if (closed) return;
80|    closed = true;
81|    if (TURNED_AWAY.has(code)) { stage = 'turnedAway'; on.turnedAway?.(code, reason); }
82|    else { stage = 'dropped'; on.dropped?.(reason); } // missing code = a plain drop
83|  };
84|
85|  conn.send(encode('join', { name }));
86|
87|  // Outgoing helpers. Each send is gated to the stage(s) that make it legal,
88|  // so a UI slip cannot put out-of-context messages on the wire.
89|  const sendIf = (legal, type, data) => { if (!closed && legal) conn.send(encode(type, data)); };
90|
91|  return {
92|    clock, // master clock: the ampel/goAt comparison uses clock.serverNow()
93|    get stage() { return stage; },
94|    get players() { return players; },
95|    get seed() { return seed; },
96|    get canStart() { return stage === 'lobby' && players.length >= 2; },
97|    get goAt() { return goAt; },
98|    /** Stream one car state; legal from the countdown (freeze phase) on. */
99|    sendPos(state) { sendIf(['countdown', 'racing', 'finished'].includes(stage), 'pos', state); },
100|    /** Report the crossing time once per race; legal while racing or after. */
101|    sendFinish(t) {
102|      if (closed || finishSent || (stage !== 'racing' && stage !== 'finished')) return;
