{"content": "1|/**
2| * Remote-car interpolation buffer: push({t, x, z, h, s}) peer snapshots in
3| * local receive time, sample(renderNow, delayMs) reads ~100 ms behind the
4| * render clock, so uneven arrival times (jitter) never show on screen.
5| * PURE and deterministic — no timers, no randomness, no DOM.
6| *
7| * Never teleports backwards: a snapshot whose t is not newer than the stored
8| * newest is ignored. Past the newest snapshot the car simply holds (clamp);
9| * the peer's next update catches it back up. Heading glides along the SHORTEST
10| * arc between snapshots (track convention: 0 = facing +z, east = +π/2).
11| * Counts toward the size budget — kept tight.
12| */
13|
14|const TAU = Math.PI * 2;
15|
16|// Angle aliases into the −π..π branch.
17|const norm = (h) => { const a = (h % TAU + TAU) % TAU; return a > Math.PI ? a - TAU : a; };
18|
19|// Snapshot state minus the bookkeeping field t: exactly what a renderer wants.
20|const pick = (q) => ({ x: q.x, z: q.z, h: q.h, s: q.s });
21|
22|/** One interpolation buffer for one remote car. */
23|export function createInterp() {
24|  const buf = []; // {t, x, z, h, s}, oldest first, newest last
25|  return {
26|    /** Store one peer snapshot in receive order; older/equal t is ignored. */
27|    push(st) {
28|      if (buf.length && st.t <= buf[buf.length - 1].t) return;
29|      buf.push({ t: st.t, x: st.x, z: st.z, h: st.h, s: st.s });
30|      if (buf.length > 64) buf.shift(); // ~4 s at 15 Hz is plenty of history
31|    },
32|    /**
33|     * Interpolated car state at renderNow − delayMs (linear position/speed,
34|     * shortest-arc heading), or null before any snapshot. Before the first /
35|     * past the newest snapshot the earliest/newest state is returned as-is.
36|     */
37|    sample(renderNow, delayMs = 100) {
38|      if (!buf.length) return null;
39|      const rT = renderNow - delayMs;
40|      if (rT <= buf[0].t) return pick(buf[0]); // play has not begun: hold the car where it first appeared
41|      let i = buf.length - 1;
42|      if (rT >= buf[i].t) return pick(buf[i]); // clamp: no extrapolation past the newest
43|      for (i = 0; buf[i + 1].t <= rT; i++); // slide to the segment [i, i+1] surrounding rT
44|      const a = buf[i], b = buf[i + 1];
45|      const f = (rT - a.t) / (b.t - a.t);
46|      return {
47|        x: a.x + (b.x - a.x) * f,
48|        z: a.z + (b.z - a.z) * f,
49|        h: norm(a.h + norm(b.h - a.h) * f), // shortest arc, back into −π..π
50|        s: a.s + (b.s - a.s) * f,
51|      };
52|    },
53|  };
54|}", "total_lines": 54, "file_size": 2411, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|/**
2| * Phase 4 client-local race maths: ampel light phases, the frozen-car start
3| * gate, ms-precise finish crossing and podium placement. PURE: no DOM, no
4| * timers, no RNG — time is injected (local ms), physics only borrowed.
5| * Counts toward the size budget — kept tight.
6| */
7|import { stepCar } from '../vehicle/carPhysics.js';
8|
9|/** How long before goAt the ampel shows red+amber (German sequence). */
10|export const AMBER_BEFORE_MS = 1000;
11|
12|/**
13| * ampelState(serverNow, goAt) → 'red' | 'red+amber' | 'green'.
14| * German sequence: solid red until the last AMBER_BEFORE_MS before the shared
15| * goAt, then red+amber, then green the instant serverNow reaches goAt.
16| */
17|export function ampelState(serverNow, goAt) {
18|  if (serverNow >= goAt) return 'green';
19|  if (serverNow >= goAt - AMBER_BEFORE_MS) return 'red+amber';
20|  return 'red';
21|}
22|
23|/**
24| * createStartGate({ isGreen, onJump }) → { step(car, input, spec, dt) }.
25| * A pure wrapper around stepCar, not an input hack: pre-green the car is
26| * physics-frozen — stepCar is never called and car is not touched. Pressing
27| * throttle while frozen fires onJump() EXACTLY once for the whole gate
28| * lifetime (jump-start hook; the server settles the penalty). Once green,
29| * every step goes straight through physics.
30| */
31|export function createStartGate({ isGreen, onJump }) {
32|  let jumped = false;
33|  return {
34|    step(car, input, spec, dt) {
35|      if (isGreen()) return stepCar(car, input, spec, dt);
36|      if (!jumped && input.throttle > 0) {
37|        jumped = true;
38|        onJump();
39|      }
40|      return car;
41|    },
42|  };
43|}
44|
45|/**
46| * crossingTime(prev, cur, finishX) → interpolated local ms at which the car's
47| * centre crossed finish.x moving EAST, else null (before the line, past it,
48| * west, or static on the line). prev/cur = { x, t } of consecutive physics
49| * steps; precision is exactly the linear interpolation of the two samples —
50| * no finer. Caller converts to server time T with the clock offset.
51| */
52|export function crossingTime(prev, cur, finishX) {
53|  if (!(prev.x < finishX && cur.x >= finishX)) return null;
54|  const f = (finishX - prev.x) / (cur.x - prev.x); // cur.x > prev.x is implied
55|  return prev.t + f * (cur.t - prev.t);
56|}
57|
58|/**
59| * podiumLayout(results, base, road) → { steps, cars } — decided, documented,
60| * deterministic ground plan (the renderer lifts taxi models by step.h itself):
61| *
62| * - minZ = min(laneMinZ, laneMaxZ) is the NORTH edge of the racing lane;
63| *   north = −z, east = +x, racing direction = heading Math.PI / 2.
64| * - Three steps (ALWAYS three, even with fewer racers) in a row NORTH of that
65| *   edge — behind the line, clear of the racing lane, no track danger: one
66| *   column x = base.x + 6, place 1 nearest the lane at z = minZ − 2, then 2
67| *   and 3 a further 2.4 m north. Boxes 2.2 × 2.2 m, heights 0.4/0.3/0.2 —
68| *   place 1 highest.
69| * - Cars: each of the top-3 finishers sits on its own step (x, step z), facing
70| *   the camera as the taxis on the grid do (heading EAST). Everyone else
71| *   (DNFs, or a 4th finisher beyond the podium) parks further north at
72| *   x = base.x + 6, z = place-3 step − 2.2 × (i + 1), in results order, each
73| *   keeping its own dnf flag, place null.
74| * - `results` is the settled server order (finishers first): podium place =
75| *   index within the non-DNF finishers; extra fields (pen) are ignored.
76| */
77|export function podiumLayout(results, base, road) {
78|  const minZ = Math.min(road.laneMinZ, road.laneMaxZ);
79|  const x = base.x + 6;
80|  const OFF = [2, 4.4, 6.8]; // north of the lane edge, per place
81|  const H = [0.4, 0.3, 0.2]; // step height, per place
82|  const EAST = Math.PI / 2;
83|  const steps = [1, 2, 3].map((p) => ({
84|    place: p, x, z: minZ - OFF[p - 1], w: 2.2, d: 2.2, h: H[p - 1],
85|  }));
86|  const cars = [];
87|  const podium = results.filter((r) => !r.dnf).slice(0, 3);
88|  for (const r of podium) {
89|    const p = podium.indexOf(r) + 1;
90|    cars.push({ id: r.id, name: r.name, x, z: steps[p - 1].z, heading: EAST, place: p, dnf: false });
91|  }
92|  const extra = results.filter((r) => r.dnf || !podium.includes(r));
93|  extra.forEach((r, i) => cars.push({
94|    id: r.id, name: r.name, x, z: steps[2].z - 2.2 * (i + 1), heading: EAST, place: null, dnf: !!r.dnf,
95|  }));
96|  return { steps, cars };
