{"content": "1|/**
2| * Pure track layout for the multiplayer race: a 200 m straight run eastwards
3| * along *Unter den Linden*, starting just past the Brandenburger-Tor-style
4| * gate (the solo mode's own spawn road). Derived ONLY from the shared city
5| * data, so every client computing it from the same seed gets the same track.
6| *
7| * Coordinates: the city generator's plane — north = −z, so east = +x and
8| * "facing east" = heading Math.PI / 2 (like cityGen's spawn).
9| *
10| * Pure data in, pure data out, runs in Node for the tests. Grid slots are
11| * validated "place-only" against the city colliders: every seat must clear
12| * buildings, medians, gate pillars and the world border before the race uses
13| * it. Counts toward the size budget — kept tight.
14| */
15|import { TAXI } from '../vehicle/carPhysics.js';
16|import { pushOut } from '../vehicle/collision.js';
17|
18|export const TRACK_LENGTH = 200;
19|const SLOT_GAP = 3.4; // grid spacing in the lane, north→south
20|const GRID_MARGIN = 1.5; // corridor clear of the colliders on both sides
21|
22|/**
23| * buildTrack(city, playerCount) →
24| *   { street, start, grid, finish, ampel, corridor, laneZ }
25| *
26| * - start   {x, z, heading}: the line the grid stands on
27| * - grid    [{x, z, heading}]: exactly playerCount seats, pole position first
28| * - finish  {x, z0, z1}: the chequered line segment across the racing lane
29| * - ampel   {x, z, heading}: the start light pole, on the central line ahead
30| * - corridor {x0, z0, x1, z1}: rect that must stay free of colliders, used
31| *   by the invariant tests ("track is fully on road, nothing in the way")
32| */
33|export function buildTrack(city, playerCount) {
34|  if (!Number.isInteger(playerCount) || playerCount < 2 || playerCount > 4)
35|    throw new RangeError('track: needs 2–4 players');
36|  const gate = city.landmarks.find((l) => l.kind === 'gate');
37|  const boulevard = city.streetsEW.find((s) => s.kind === 'boulevard');
38|  if (!gate || !boulevard) throw new RangeError('track: city has no boulevard or gate');
39|  const cfg = city.config;
40|
41|  // Start past the first north-south crossing east of the gate, so the grid
42|  // stands on an ordinary stretch of the boulevard, not across a junction.
43|  // (The solo mode's spawn is gate.x + 30 — at least that far east.)
44|  const crossing = city.streetsNS.find((s) => s.center + s.width / 2 > gate.x + 10);
45|  const start = {
46|    x: Math.max(gate.x + 30, (crossing ? crossing.center + crossing.width / 2 : gate.x) + 8),
47|    z: boulevard.center + cfg.medianWidth / 2 + 3.5,
48|    heading: Math.PI / 2,
49|  };
50|  const finish = {
51|    x: start.x + TRACK_LENGTH,
52|    z0: boulevard.center + cfg.medianWidth / 2 + GRID_MARGIN,
53|    z1: boulevard.center + cfg.boulevardWidth / 2 - GRID_MARGIN,
54|  };
55|  if (finish.x + GRID_MARGIN > city.bounds.x1 - 10)
56|    throw new RangeError('track: 200 m do not fit east of the gate');
57|
58|  // Seats side by side across the racing lane, starting just inside the clear band.
59|  const grid = Array.from({ length: playerCount }, (_, i) => ({
60|    x: start.x,
61|    z: start.z - 1.5 + i * SLOT_GAP,
62|    heading: Math.PI / 2,
63|  }));
64|  for (const slot of grid) {
65|    for (const off of [TAXI.collisionOffset, -TAXI.collisionOffset]) {
66|      if (pushOut(slot.x + off, slot.z, TAXI.collisionRadius, city.colliders))
67|        throw new RangeError('track: grid slot collides with the city');
68|    }
69|  }
70|  for (let a = 0; a < grid.length; a++)
71|    for (let b = a + 1; b < grid.length; b++)
72|      if (Math.hypot(grid[a].x - grid[b].x, grid[a].z - grid[b].z) < SLOT_GAP - 0.2)
73|        throw new RangeError('track: grid slots overlap');
74|
75|  const corridor = {
76|    x0: start.x - GRID_MARGIN * 1.5,
77|    z0: boulevard.center + cfg.medianWidth / 2 + 0.5,
78|    x1: finish.x + GRID_MARGIN,
79|    z1: boulevard.center + cfg.boulevardWidth / 2 - 0.5,
80|  };
81|  for (const c of city.colliders) {
82|    if (c.type === 'box') {
83|      if (c.x0 < corridor.x1 && c.x1 > corridor.x0 && c.z0 < corridor.z1 && c.z1 > corridor.z0)
84|        throw new RangeError('track: something box-shaped is standing in the corridor');
85|    } else if (Math.max(corridor.x0 - c.x, c.x - corridor.x1, 0) ** 2 + Math.max(corridor.z0 - c.z, c.z - corridor.z1, 0) ** 2 < c.r * c.r)
86|      throw new RangeError('track: something round is standing in the corridor');
87|  }
88|
89|  return {
90|    street: 'Unter den Linden',
91|    start,
92|    grid,
93|    finish,
94|    ampel: { x: start.x + 12, z: boulevard.center, heading: -Math.PI / 2 },
95|    corridor,
96|    laneZ: start.z,
97|  };
98|}", "total_lines": 98, "file_size": 4415, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|/**
2| * FairFahren — entry point. Wires world generation, physics, rendering and input.
3| *
4| *   generateCity(seed) ──► city data ──► buildCityMesh ──► GPU (static)
5| *                               │
6| *   Keyboard ──► stepCar ──► collideCar(city.colliders) ──► Camera ──► Renderer
7| *
8| * Solo (`npm start`) is the pre-multiplayer game, unchanged — no sockets, no
9| * overlays. `?online` joins the race server instead: lobby overlay, shared
10| * city, remote taxis, ampel start gate, finish line, results and podium
11| * (phases 3–4, docs/plans/g-multiplayer).
12| */
13|import { generateCity, streetAt } from './world/cityGen.js';
14|import { buildCityMesh } from './world/cityMesh.js';
15|import { TAXI, createCar, stepCar } from './vehicle/carPhysics.js';
16|import { collideCar } from './vehicle/collision.js';
17|import { buildTaxi, wheelOffsets } from './vehicle/taxiModel.js';
18|import { Renderer } from './gfx/renderer.js';
19|import { MeshBuilder, MAT, rgb } from './gfx/meshBuilder.js';
20|import { Keyboard } from './game/input.js';
21|import { Camera } from './game/camera.js';
22|import { Hud } from './game/hud.js';
23|import { compose, translation, rotationX, rotationY, perspective, lookAt } from './core/math.js';
24|import { encode } from '../server/protocol.js';
25|import { createNetClient } from './net/client.js';
26|import { createInterp } from './net/remoteCar.js';
27|import { buildTrack } from './net/track.js';
28|import { ampelState, createStartGate, crossingTime, podiumLayout } from './net/raceLocal.js';
29|
30|const PHYSICS_STEP = 1 / 120; // fixed timestep keeps physics deterministic
31|const ENV = {
32|  sunDir: normalize([0.35, 0.8, 0.5]),
33|  fogColor: [0.75, 0.79, 0.84], // hazy Berlin sky
34|  fogDensity: 0.0016,
35|  time: 0,
36|};
37|
38|const seedParam = Number.parseInt(new URLSearchParams(location.search).get('seed') ?? '', 10);
39|const ONLINE = new URLSearchParams(location.search).has('online');
40|let city = generateCity(Number.isFinite(seedParam) ? { seed: seedParam } : {});
41|
42|let renderer;
43|try {
44|  renderer = new Renderer(document.querySelector('canvas'));
45|} catch (err) {
46|  document.querySelector('#error').textContent = err.message;
47|  throw err;
48|}
49|
50|let cityMesh = renderer.upload(buildCityMesh(city));
51|const taxiParts = buildTaxi(TAXI);
52|const taxi = { body: renderer.upload(taxiParts.body), wheel: renderer.upload(taxiParts.wheel), shadow: renderer.upload(taxiParts.shadow) };
53|const wheels = wheelOffsets(TAXI);
54|
55|const car = createCar(city.spawn);
56|const keyboard = new Keyboard(window);
57|const camera = new Camera();
58|const hud = new Hud(document);
59|hud.set('seed', `Seed ${city.seed}`);
60|
61|// Handy for debugging in the browser console and for automated checks.
62|window.fairfahren = { city, car, camera, TAXI };
63|
64|let last = performance.now(), accumulator = 0, fps = 60;
65|
66|// ---------------------------------------------------------------------------
67|// Online mode
68|// ---------------------------------------------------------------------------
69|// Player colours, keyed by ROSTER position (every client gets the same roster
70|// array, so id → colour is identical everywhere). They paint the body-stripe
71|// skirt and the lobby legend dots; in-world name tags were cut (NOTES.md).
72|const COLORS = [0xd23b3b, 0x3b8fd2, 0x46c05f, 0xd2a24c];
73|const cssColor = (i) => `#${COLORS[i].toString(16).padStart(6, '0')}`;
74|
75|const ui = {
76|  lobby: document.querySelector('#lobby'), joinRow: document.querySelector('#joinRow'),
77|  name: document.querySelector('#name'), roster: document.querySelector('#roster'),
78|  startBtn: document.querySelector('#startBtn'), status: document.querySelector('#netStatus'),
79|  results: document.querySelector('#results'), modal: document.querySelector('#modal'),
80|  modalMsg: document.querySelector('#modalMsg'), reloadBtn: document.querySelector('#reloadBtn'),
81|  againBtn: document.querySelector('#againBtn'),
82|};
83|
84|let net = null, selfId = null, goAt = null, gate = null, track = null, trackFor = '';
85|let ampel = null, gridded = false, prevCross = null, lastPos = 0, results = null;
86|let myFinish = null, ownT = null, otherFinishes = [], podium = null, orbit = 0;
87|let terminated = false; // turn-away or dropped: the modal owns the screen from here
88|const remotes = new Map(); // peer id → { interp, spin }
89|const jumps = new Map(); // id → penalty ms, server-settled (we only report the attempt)
90|const stripes = COLORS.map(() => null); // colour skirt meshes, built lazily
91|
92|if (ONLINE) setupOnline();
93|
94|function setupOnline() {
95|  ui.lobby.hidden = false;
96|  ui.name.focus();
97|  document.querySelector('#joinBtn').onclick = join; // createNetClient sends 'join'
98|  ui.reloadBtn.onclick = () => location.reload();
99|  ui.againBtn.onclick = () => net?.sendRaw(encode('again', {})); // only legal in ceremony
100|}
101|
102|function join() {
103|  if (net) return;
104|  document.querySelector('#joinBtn').disabled = true;
105|  const ws = new WebSocket(`ws://${location.host}/ws`);
106|  // The net client fills the two callback slots; the WebSocket fills send/close.
107|  // A just-created socket refuses send() until open, so early frames (the
108|  // constructor's join, the first ping) are queued and flushed on open.
109|  const early = [];
110|  const conn = {
111|    send: (t) => { if (ws.readyState === 1) ws.send(t); else early.push(t); },
112|    close: () => ws.close(),
113|    onMessage: null,
114|    onClose: null,
115|  };
116|  ws.onopen = () => { for (const t of early) ws.send(t); early.length = 0; };
117|  ws.onmessage = (e) => conn.onMessage?.(e.data);
118|  ws.onclose = (e) => conn.onClose?.(e.code, e.reason); // 4000/4001 reach on.turnedAway
119|  net = createNetClient({
120|    conn,
121|    name: ui.name.value.trim() || 'Fahrer',
122|    now: () => performance.now(), // the client's clock lives in local ms
123|    every: (ms, fn) => { const h = setInterval(fn, ms); return () => clearInterval(h); },
124|    on: {
125|      roster: (players, seed) => { rebuildWorld(seed); onRoster(players); },
126|      stage: onStage,
127|      goAt: (g) => { goAt = g; },
128|      peerPos: ({ id, t, x, z, h, s }) => {
129|        const r = remotes.get(id) ?? remotes.set(id, { interp: createInterp(), spin: 0 }).get(id);
130|        r.interp.push({ t, x, z, h, s });
131|      },
132|      peerGone: (id) => remotes.delete(id),
133|      jumped: ({ id, pen }) => jumps.set(id, pen),
134|      finishInfo: ({ id, t }) => { if (id === selfId) ownT = t; else otherFinishes.push(t); },
135|      results: showResults,
136|      turnedAway: (code) => showModal(code === 4000 ? 'Stadt voll — versuch es später wieder.' : 'Rennen läuft schon — versuch es gleich nochmal.'),
137|      dropped: () => showModal('Verbindung verloren.'),
138|    },
139|  });
140|}
141|
142|/** The server's seed wins: regenerate city + static mesh synchronously (~1 ms). */
143|function rebuildWorld(seed) {
144|  if (seed === null || seed === city.seed) return;
