{"content": "1|// Phase 2: every rule of the race, driven END-TO-END through fakeNet pairs —
2|// joins → start → positions → finishes → results → ceremony, no real socket.
3|import { test } from 'node:test';
4|import assert from 'node:assert/strict';
5|import { FakeNet, FakeServer } from '../server/fakeNet.js';
6|import { createRaceState, CLOSE_FULL, CLOSE_STARTED, JUMP_PENALTY_MS } from '../server/raceState.js';
7|import { decode, encode } from '../server/protocol.js';
8|
9|// A wired-up server + client handles on the virtual network. Each client
10|// records every message it is sent as {type, data}; `client.send(type, data)`
11|// encodes + delivers with the client's injected latency.
12|function world({ latency = 0 } = {}) {
13|  const net = new FakeNet();
14|  const server = new FakeServer(net);
15|  const rejected = []; // every { code, reason } the server turned someone away with
16|  const race = createRaceState({
17|    seed: 42,
18|    now: () => net.now,
19|    send: (conn, type, data) => conn.send(encode(type, data)),
20|    close: (conn, code, reason) => {
21|      rejected.push({ code, reason }); // visible even though the reject fires before any client handler exists
22|      conn.close(code, reason);
23|    },
24|    schedule: (delayMs, fn) => net.schedule(delayMs, fn),
25|  });
26|  server.onConnect = (conn) => {
27|    race.connect(conn);
28|    conn.onMessage = (text) => race.onMessage(conn, text);
29|    conn.onClose = () => race.disconnect(conn);
30|  };
31|  const client = (opts) => {
32|    const conn = server.connect({ latency });
33|    const me = { conn, messages: [], id: null, closedWith: null };
34|    conn.onMessage = (text) => {
35|      const m = decode(text);
36|      me.messages.push(m);
37|      if (m.type === 'roster') me.id = m.data.players.find((p) => p.name === me.name)?.id ?? me.id;
38|    };
39|    conn.onClose = () => { me.closedWith = conn.closedWith; };
40|    me.name = null;
41|    me.join = (name) => {
42|      me.name = name;
43|      conn.send(encode('join', { name }));
44|      return me;
45|    };
46|    me.send = (type, data) => conn.send(encode(type, data));
47|    me.saw = (type) => me.messages.filter((m) => m.type === type);
48|    return me;
49|  };
50|  return { net, race, client, rejected };
51|}
