{"content": "1|// Phase 3: the net client (src/net/client.js), driven END-TO-END through
2|// fakeNet against the real raceState — join, roster, seed, start gate, stage,
3|// turn-away, clean drop, master-clock pings, finish gating, results.
4|import { test } from 'node:test';
5|import assert from 'node:assert/strict';
6|import { FakeNet, FakeServer } from '../server/fakeNet.js';
7|import { createRaceState, CLOSE_FULL } from '../server/raceState.js';
8|import { decode, encode } from '../server/protocol.js';
9|import { createNetClient } from '../src/net/client.js';
10|
11|// A wired server + turnkey net clients on the virtual network. The server
12|// remembers every client message raw (`saw(type)` counts them); each client
13|// records all callbacks in `c.log`.
14|function world({ seed = 42, latency = 0 } = {}) {
15|  const net = new FakeNet();
16|  const server = new FakeServer(net);
17|  const onWire = []; // raw texts exactly as the server received them
18|  const rejects = new Map(); // client conn → { code, reason } the server turned it away with
19|  const race = createRaceState({
20|    seed,
21|    now: () => net.now,
22|    send: (conn, type, data) => conn.send(encode(type, data)),
23|    close: (conn, code, reason) => {
24|      conn.close(code, reason);
25|      // fakeNet's peer side fires onClose() without the code (it is only
26|      // recorded on the closer); the real socket delivers it asynchronously
27|      // with its code. Remember it here and hand it to the client below.
28|      rejects.set(conn.peer, { code, reason });
29|    },
30|    schedule: (delayMs, fn) => net.schedule(delayMs, fn),
31|  });
32|  server.onConnect = (conn) => {
33|    race.connect(conn);
34|    conn.onMessage = (text) => { onWire.push(text); race.onMessage(conn, text); };
35|    conn.onClose = () => race.disconnect(conn);
36|  };
37|  const saw = (type) => onWire.map((t) => { try { return decode(t).type; } catch { return `raw:${t}`; } }).filter((ty) => ty === type);
38|  const client = (name) => {
39|    const conn = server.connect({ latency });
40|    const log = {
41|      roster: [], seedChange: [], stage: [], goAt: [], peerPos: [], peerGone: [],
42|      finishInfo: [], results: [], turnedAway: [], dropped: [], jumped: [],
43|    };
44|    const c = createNetClient({
45|      conn, name, now: () => net.now, every: (ms, fn) => net.schedule(ms, fn),
46|      on: {
47|        roster: (players, s) => log.roster.push({ players, seed: s }),
48|        seedChange: (s) => log.seedChange.push(s),
49|        stage: (s) => log.stage.push(s),
50|        goAt: (g) => log.goAt.push(g),
51|        peerPos: (state) => log.peerPos.push(state),
52|        peerGone: (id) => log.peerGone.push(id),
53|        finishInfo: (f) => log.finishInfo.push(f),
54|        jumped: (j) => log.jumped.push(j),
55|        results: (players) => log.results.push(players),
56|        turnedAway: (code, reason) => log.turnedAway.push({ code, reason }),
57|        dropped: (reason) => log.dropped.push(reason),
58|      },
59|    });
60|    c.conn = conn;
61|    c.log = log;
62|    // Replay the turn-away fakeNet fired before any client handler could
63|    // exist (see world.close). The real socket delivers this late, code in hand.
64|    const rej = rejects.get(conn);
65|    if (rej) conn.onClose(rej.code, rej.reason);
66|    return c;
67|  };
68|  return { net, race, client, saw };
69|}
