74|  net.advance(0);
75|  assert.equal(a.stage, 'lobby');
76|  assert.deepEqual(a.log.seedChange, [42], 'seedChange fires once for the first roster');
77|  assert.equal(a.canStart, false, 'a lone player cannot start a race');
78|  a.startRace();
79|  assert.equal(a.stage, 'lobby', 'start with 1 player does nothing');
80|
81|  const b = client('B');
82|  net.advance(0);
83|  for (const c of [a, b]) {
84|    assert.deepEqual(c.players.map((p) => p.name).sort(), ['A', 'B']);
85|    assert.equal(c.seed, 42);
86|    assert.equal(c.canStart, true, 'two players open the gate');
87|    assert.deepEqual(c.log.seedChange, [42], 'the same seed never re-fires seedChange');
88|  }
89|  assert.ok(a.log.roster.length === 2, 'roster fired on every roster message for A');
90|  assert.ok(b.log.roster.length === 1, 'roster fired once for late joiner B');
91|
