94|  assert.equal(b.stage, 'countdown', 'stage message reached B');
95|  assert.equal(a.goAt, b.goAt, 'one shared goAt');
96|  assert.equal(new Set(b.log.goAt).size, 1, 'countdown and go carry the same goAt');
97|
98|  net.advance(3000);
99|  assert.equal(a.stage, 'racing');
100|  assert.equal(b.stage, 'racing');
101|
102|  a.sendPos({ x: 1, z: 2, h: 0.5, s: 3 });
103|  net.advance(0);
104|  const relay = b.log.peerPos[0];
105|  assert.ok(relay, 'posRelay flowed through sendPos to the peer');
106|  assert.equal(relay.x, 1);
107|  assert.equal(relay.z, 2);
108|  assert.equal(relay.h, 0.5);
109|  assert.equal(relay.s, 3);
110|  assert.equal(relay.id, a.players.find((p) => p.name === 'A').id, 'relayed under A id');
111|  assert.ok(Number.isFinite(relay.t), 'receive time is attached for the interp buffer');
112|
113|  // sendPos is gated: nobody races from the lobby.
114|  const fresh = world();
115|  const lone = fresh.client('Lone');
116|  fresh.net.advance(0);
117|  lone.sendPos({ x: 1, z: 2, h: 0, s: 0 });
118|  fresh.net.advance(0);
119|  assert.deepEqual(fresh.saw('pos'), [], 'no positions leave the lobby');
