{"content": "1|// The full race loop, browser-free, over the REAL modules: two net clients
2|// (src/net/client.js) paired through fakeNet against the real raceState, with
3|// physics cars placed on a track derived from the shared world. One test runs
4|// lobby → shared countdown → jump start → finishes → settled results →
5|// ceremony → Nochmal rematch → a second clean race. Everything runs on
6|// fakeNet's virtual clock (net.advance) — no timers, fully deterministic.
7|import { test } from 'node:test';
8|import assert from 'node:assert/strict';
9|import { FakeNet, FakeServer } from '../server/fakeNet.js';
10|import { createRaceState, JUMP_PENALTY_MS } from '../server/raceState.js';
11|import { decode, encode } from '../server/protocol.js';
12|import { createNetClient } from '../src/net/client.js';
13|import { ampelState, createStartGate, crossingTime } from '../src/net/raceLocal.js';
14|import { createCar, stepCar, TAXI } from '../src/vehicle/carPhysics.js';
15|import { buildTrack } from '../src/net/track.js';
16|import { generateCity } from '../src/world/cityGen.js';
17|
18|const DT = 1 / 60; // physics slice, like the browser game loop
19|const STEP = 1000 / 60; // the same slice on the virtual network clock
20|const WIRE = 10; // symmetric latency in ms — gives the pings a real round trip
21|
22|// A wired server + turnkey net clients on the virtual network. Each client
23|// records every on.* callback in `c.log` and every incoming frame in `c.raw`.
24|function wiredNet({ seed = 42, latency = WIRE } = {}) {
25|  const net = new FakeNet();
26|  const server = new FakeServer(net);
27|  const race = createRaceState({
28|    seed,
29|    now: () => net.now,
30|    send: (conn, type, data) => conn.send(encode(type, data)),
31|    close: (conn, code, reason) => conn.close(code, reason),
32|    schedule: (ms, fn) => net.schedule(ms, fn),
33|  });
34|  server.onConnect = (conn) => {
35|    race.connect(conn);
36|    conn.onMessage = (text) => race.onMessage(conn, text);
37|    conn.onClose = () => race.disconnect(conn);
38|  };
39|  const client = (name) => {
40|    const conn = server.connect({ latency });
41|    const log = {
42|      roster: [], seedChange: [], stage: [], goAt: [], peerPos: [],
43|      finishInfo: [], results: [], turnedAway: [], dropped: [],
44|    };
45|    const c = createNetClient({
46|      conn, name, now: () => net.now, every: (ms, fn) => net.schedule(ms, fn),
47|      on: {
48|        roster: (players, s) => log.roster.push({ players, seed: s }),
49|        seedChange: (s) => log.seedChange.push(s),
50|        stage: (s) => log.stage.push(s),
51|        goAt: (g) => log.goAt.push(g),
52|        peerPos: (p) => log.peerPos.push(p),
53|        finishInfo: (f) => log.finishInfo.push(f),
54|        results: (rows) => log.results.push(rows),
55|        turnedAway: (code, reason) => log.turnedAway.push({ code, reason }),
56|        dropped: (reason) => log.dropped.push(reason),
57|      },
58|    });
59|    // Tee every arriving frame for wire-level assertions ('jumped' has no
60|    // client handler — it is observed here and in the results only).
61|    const inner = conn.onMessage;
62|    c.raw = [];
63|    c.log = log;
64|    conn.onMessage = (text) => { c.raw.push(decode(text)); inner(text); };
65|    return c;
66|  };
67|  return { net, race, client };
68|}
69|
70|// One whole race on the virtual clock: waits through the German ampel, holds
71|// the grid frozen behind the start gate (optionally one jump-start press by B
72|// while the light is still red+amber), then runs 60 Hz physics eastwards,
73|// streams 15 Hz positions and reports each crossing as elapsed race time on
74|// the master clock. Returns the track plus per-side { t } report times.
75|function driveRace({ net, a, b, press = false }) {
76|  const track = buildTrack(generateCity({ seed: a.seed }), 2);
77|  const serverNow = (c) => c.clock.serverNow(net.now); // master-clock view
78|  const ampel = (c) => ampelState(serverNow(c), c.goAt);
79|  assert.ok(a.clock.synced() && b.clock.synced(), 'both clocks are pong-synced before the light turns amber');
80|  assert.equal(a.goAt, b.goAt, 'one shared start moment');
81|
82|  // A side of the grid: a fresh car behind a fresh start gate on its client's
83|  // own clock. Pre-green the gate freezes the car — physics never runs early.
84|  const side = (c, throttle, slot) => {
85|    const s = { client: c, car: createCar(track.grid[slot]), throttle, jumped: 0, t: null, last: null };
86|    s.gate = createStartGate({
87|      isGreen: () => serverNow(c) >= c.goAt,
88|      onJump: () => { s.jumped += 1; c.sendRaw(encode('jump', {})); },
89|    });
90|    return s;
91|  };
92|  const A = side(a, 0.8, 0); // throttled just enough for B's penalty to decide
93|  const B = side(b, 1, 1);
94|
95|  assert.equal(ampel(B.client), 'red', 'solid red while the countdown runs');
96|  while (ampel(B.client) === 'red') net.advance(STEP);
97|  assert.equal(ampel(B.client), 'red+amber', 'red+amber precedes the green');
98|  if (press) {
99|    const press1 = { throttle: 1, brake: 0, steer: 0, handbrake: false };
100|    B.gate.step(B.car, press1, TAXI, DT); // frozen: car untouched, onJump fires
101|    assert.equal(B.jumped, 1, 'the frozen gate reports a jump start exactly once');
102|  }
103|  while (ampel(B.client) === 'red+amber') net.advance(STEP);
104|  assert.equal(ampel(B.client), 'green', 'the shared light turns green on every client');
105|  assert.equal(ampel(A.client), 'green');
106|
107|  // The race: fixed timestep, positions into the relay, crossings interpolated.
108|  const sides = [A, B];
109|  let frame = 0;
110|  while (sides.some((s) => s.t === null) && frame++ < 6000) {
111|    net.advance(STEP);
112|    for (const s of sides) {
113|      if (s.t !== null) continue; // crossed: parked until the race settles
114|      const prev = s.last ?? { x: s.car.x, t: net.now };
115|      s.gate.step(s.car, { throttle: s.throttle, brake: 0, steer: 0, handbrake: false }, TAXI, DT);
116|      const cur = { x: s.car.x, t: net.now };
117|      s.last = cur;
118|      const hit = crossingTime(prev, cur, track.finish.x);
119|      if (hit !== null) s.t = Math.round(s.client.clock.serverNow(hit) - s.client.goAt);
120|      else if (frame % 6 === 0) s.client.sendPos({ x: s.car.x, z: s.car.z, h: s.car.heading, s: s.car.speed });
121|    }
122|  }
123|  assert.ok(sides.every((s) => Number.isFinite(s.t) && s.t > 0), 'both sides crossed inside the sim window');
124|  return { track, A, B };
125|}
126|
127|test('lobby → jump start → settled results → ceremony → Nochmal rematch → clean second race', () => {
128|  const { net, client } = wiredNet({ seed: 42 });
129|  const a = client('Anna');
130|  const b = client('Ben');
131|  const idOf = (c) => c.players.find((p) => p.name === (c === a ? 'Anna' : 'Ben')).id;
132|  const saw = (c, type) => c.raw.filter((m) => m.type === type);
133|
134|  // a) two joins on the wire → one lobby, same seed, start gate open
135|  net.advance(2 * WIRE + 5); // joins hop over, rosters come back
136|  for (const c of [a, b]) {
137|    assert.equal(c.stage, 'lobby');
138|    assert.equal(c.players.length, 2);
139|    assert.equal(c.seed, 42, 'the shared world arrives with the roster');
140|    assert.ok(c.canStart, 'two players open the start gate');
141|  }
142|  assert.deepEqual(a.seed, b.seed);
143|
144|  // b) one start press → shared countdown on both clients, roster unchanged
145|  a.startRace();
146|  net.advance(WIRE * 2 + 10);
147|  for (const c of [a, b]) {
148|    assert.equal(c.stage, 'countdown');
149|    assert.ok(Number.isFinite(c.goAt) && c.goAt > net.now, 'green lies ahead on the server clock');
150|    assert.equal(c.players.length, 2, 'the roster did not change at the start');
151|  }
152|  assert.equal(a.goAt, b.goAt, 'one shared goAt');
153|
154|  // i) master-clock sync: the lobby pings echoed back before any green
155|  net.advance(1000);
156|  for (const c of [a, b]) assert.ok(c.clock.synced() && c.clock.offset() !== null, 'pong-fed clock offset available');
157|
158|  // c) B jumps the light: frozen gate reports exactly once, the server fixes
159|  // the penalty itself (the jump press carries no size, only the report).
160|  const r1 = driveRace({ net, a, b, press: true });
161|  assert.deepEqual(saw(a, 'jumped'), [{ type: 'jumped', data: { id: idOf(b), pen: JUMP_PENALTY_MS } }],
162|    'exactly one jumped broadcast, penalty set by the server alone');
163|  assert.ok(r1.B.t < r1.A.t, 'raw times: clean B crossed first');
164|  assert.ok(r1.B.t + JUMP_PENALTY_MS > r1.A.t, 'the penalty is what flips the podium');
165|  let mark = a.log.peerPos.length;
166|  const relaysA = a.log.peerPos.filter((p) => p.id === idOf(b));
167|  assert.ok(relaysA.length > 10, 'B streamed positions into A\'s interp buffer');
168|  for (let i = 1; i < relaysA.length; i++) assert.ok(relaysA[i].x > relaysA[i - 1].x, 'relayed x never goes back');
169|
170|  // d/e) finish reports while racing → settled order = reported time + penalty
171|  a.sendFinish(r1.A.t);
172|  b.sendFinish(r1.B.t);
173|  net.advance(WIRE * 2 + 5);
174|  const rows = (c) => c.log.results[c.log.results.length - 1];
175|  assert.deepEqual(rows(a), rows(b), 'both clients saw the same settled table');
176|  assert.deepEqual(rows(a).map((r) => r.id), [idOf(a), idOf(b)], 'server reorders: penalty time beats raw time');
177|  assert.deepEqual(rows(a).map((r) => r.t), [r1.A.t, r1.B.t]);
178|  assert.deepEqual(rows(a).map((r) => r.pen), [0, JUMP_PENALTY_MS]);
179|  assert.deepEqual(rows(a).map((r) => r.dnf), [false, false]);
180|  assert.deepEqual(new Set(b.log.finishInfo.map((f) => f.id)), new Set([idOf(a), idOf(b)]), 'both finishes echoed');
181|  assert.ok(a.log.stage.includes('finished'));
182|
183|  // f) podium: the ceremony stage follows the results pause
184|  net.advance(2000 + WIRE * 2);
185|  for (const c of [a, b]) assert.equal(c.stage, 'ceremony');
186|
187|  // g) Nochmal from the ceremony: seed +1, fresh countdown, same racers
188|  mark = a.log.peerPos.length;
189|  a.sendRaw(encode('again', {}));
190|  net.advance(WIRE * 2 + 10);
191|  for (const c of [a, b]) {
192|    assert.equal(c.stage, 'countdown', 'one press throws the race away and re-grids everyone');
193|    assert.equal(c.seed, 43, 'the rematch drives the NEXT generated world');
194|    assert.ok(c.goAt > net.now, 'a fresh countdown is running');
195|    assert.equal(c.players.length, 2, 'ids and names survive the rematch');
196|  }
197|  assert.deepEqual(a.log.seedChange, [42, 43], 'the new world reached the clients exactly once');
198|  assert.deepEqual(saw(a, 'jumped').length, 1, 'the rematch started clean');
199|
200|  // h) the rematch race, no foul: clean B also wins here — on raw pace, place 1
201|  const r2 = driveRace({ net, a, b });
202|  assert.notStrictEqual(r2.track.start.x, r1.track.start.x, 'seed + 1 laid out a different stretch of track');
203|  assert.ok(r2.B.t < r2.A.t, 'B wins the rematch on raw pace');
204|  const relays2 = a.log.peerPos.slice(mark).filter((p) => p.id === idOf(b));
205|  assert.ok(relays2.length > 10, 'the second race streamed positions again');
206|  for (let i = 1; i < relays2.length; i++) assert.ok(relays2[i].x > relays2[i - 1].x, 'relay x never goes back (race 2)');
207|  a.sendFinish(r2.A.t); // the roster reset per-race reporting: no stale penalty
208|  b.sendFinish(r2.B.t);
209|  net.advance(WIRE * 2 + 5);
210|  const rows2 = (c) => c.log.results[c.log.results.length - 1];
211|  assert.deepEqual(rows2(a), rows2(b), 'same settled table after the rematch');
212|  assert.deepEqual(rows2(a).map((r) => r.id), [idOf(b), idOf(a)], 'clean winner first, no stale penalty');
213|  assert.deepEqual(rows2(a).map((r) => r.t), [r2.B.t, r2.A.t]);
214|  assert.deepEqual(rows2(a).map((r) => r.pen), [0, 0]);
215|  assert.deepEqual(rows2(a).map((r) => r.dnf), [false, false]);
216|
217|  net.advance(2000 + WIRE * 2);
218|  for (const c of [a, b]) assert.equal(c.stage, 'ceremony', 'the rematch ends on the podium too');
219|  assert.deepEqual(a.log.stage, ['countdown', 'racing', 'finished', 'ceremony', 'countdown', 'racing', 'finished', 'ceremony'],
220|    'the full stage sequence, once per race');
221|  for (const c of [a, b]) assert.deepEqual([...c.log.turnedAway, ...c.log.dropped], [], 'nobody was turned away or dropped');
