{"content": "1|// Phase 4: client-local race maths (src/net/raceLocal.js) — ampel phases off
2|// the shared clock, the frozen-car start gate (jump-start hook), ms-precise
3|// finish-line crossing, podium geometry. All pure: no DOM, no timers, no RNG.
4|import { test } from 'node:test';
5|import assert from 'node:assert/strict';
6|import { TAXI, createCar, stepCar } from '../src/vehicle/carPhysics.js';
7|import {
8|  AMBER_BEFORE_MS,
9|  ampelState,
10|  createStartGate,
11|  crossingTime,
12|  podiumLayout,
13|} from '../src/net/raceLocal.js';
14|
15|// --- Ampel: red → red+amber (1 s) → green, at the exact server boundaries ---
16|
17|test('ampel goes red, red+amber at −1000 ms, green exactly at goAt', () => {
18|  assert.equal(AMBER_BEFORE_MS, 1000);
19|  const goAt = 60000;
20|  assert.equal(ampelState(goAt - 1001, goAt), 'red', 'before the amber window');
21|  assert.equal(ampelState(goAt - 1000, goAt), 'red+amber', 'amber window starts exactly 1000 ms early');
22|  assert.equal(ampelState(goAt - 1, goAt), 'red+amber');
23|  assert.equal(ampelState(goAt, goAt), 'green', 'green exactly at goAt, not one ms later');
24|  assert.equal(ampelState(goAt + 5000, goAt), 'green');
25|});
26|
27|// --- Start gate: frozen pre-green, onJump exactly once, full physics green ---
28|
29|test('gate freezes the car completely pre-green and fires onJump exactly once', () => {
30|  let green = false;
31|  let jumps = 0;
32|  const gate = createStartGate({ isGreen: () => green, onJump: () => { jumps++; } });
33|  const car = createCar({ x: 10, z: 20, heading: Math.PI / 2 });
34|  const before = { ...car };
35|  const press = { throttle: 1, brake: 0, steer: 0, handbrake: false };
36|  const release = { throttle: 0, brake: 0, steer: 0, handbrake: false };
37|  // Press, release, press again — physics may not move a single field.
38|  for (let i = 0; i < 30; i++) {
39|    gate.step(car, i % 2 ? release : press, TAXI, 1 / 60);
40|    assert.deepEqual(car, before, 'pre-green: the car state object is untouched');
41|  }
42|  assert.equal(jumps, 1, 'many presses over many ticks, exactly one jump-start report');
43|});
44|
45|test('green gate steps exactly like stepCar and never re-fires onJump', () => {
46|  const press = { throttle: 1, brake: 0, steer: 0.5, handbrake: false };
47|  const gate = createStartGate({ isGreen: () => true, onJump: () => assert.fail('onJump fired after green') });
48|  const a = createCar({ x: 10, z: 20, heading: Math.PI / 2 });
49|  const b = createCar({ x: 10, z: 20, heading: Math.PI / 2 });
50|  for (let i = 0; i < 120; i++) {
51|    gate.step(a, press, TAXI, 1 / 60);
52|    stepCar(b, press, TAXI, 1 / 60);
53|  }
54|  assert.deepEqual(a, b, 'identical input history → identical car state');
55|  assert.ok(a.x > 10, 'the car actually moved');
56|});
57|
58|test('gate: after a jump, once green resumes, onJump never fires again', () => {
59|  let green = false;
60|  let jumps = 0;
61|  const gate = createStartGate({ isGreen: () => green, onJump: () => { jumps++; } });
62|  const press = { throttle: 1, brake: 0, steer: 0, handbrake: false };
63|  const car = createCar({ x: 0, z: 0, heading: Math.PI / 2 });
64|  for (let i = 0; i < 5; i++) gate.step(car, press, TAXI, 1 / 60); // jump-start
65|  green = true;
66|  for (let i = 0; i < 30; i++) gate.step(car, press, TAXI, 1 / 60); // full throttle away
67|  assert.equal(jumps, 1, 'the green phase steps naturally, no second report');
68|  assert.ok(car.x > 0, 'stepping resumed through the gate');
69|});
70|
71|// --- Finish line: crossing at ms precision, null in every other case ---
72|
73|test('crossingTime interpolates the exact local ms of the eastward crossing', () => {
74|  // 1 m per 100 ms, crossing the line half-way through the step.
75|  const t = crossingTime({ x: 99.5, t: 500 }, { x: 100.5, t: 600 }, 100);
76|  assert.equal(t, 550);
77|});
78|
79|test('crossingTime returns null in every other case', () => {
80|  const fx = 100;
81|  assert.equal(crossingTime({ x: 50, t: 0 }, { x: 99.9, t: 100 }, fx), null, 'not yet at the line');
82|  assert.equal(crossingTime({ x: 100.1, t: 0 }, { x: 110, t: 100 }, fx), null, 'already past the line');
83|  assert.equal(crossingTime({ x: 110, t: 0 }, { x: 99.9, t: 100 }, fx), null, 'driving west is not a finish');
84|  assert.equal(crossingTime({ x: 100, t: 0 }, { x: 100, t: 50 }, fx), null, 'static car sitting on the line');
85|  assert.equal(crossingTime({ x: 100, t: 0 }, { x: 101, t: 50 }, fx), null, 'prev already on the line');
86|});
87|
88|test('crossingTime: a straight eastward drive crosses exactly once', () => {
89|  const fx = 100;
90|  const found = [];
91|  for (let i = 0; i < 60; i++) {
92|    const prev = { x: 50 + i * 2, t: i * 100 };
93|    const cur = { x: 50 + (i + 1) * 2, t: (i + 1) * 100 };
94|    const t = crossingTime(prev, cur, fx);
95|    if (t !== null) found.push(t);
96|  }
97|  assert.deepEqual(found, [2500]);
98|});
99|
100|// --- Podium: deterministic placement for places 1..3 and every DNF ---
101|
102|test('podium: winner highest and nearest the lane, DNFs parked in a row south', () => {
103|  // Like the real track: z0 (laneMinZ) north of z1, the racing lane between.
104|  const road = { laneMinZ: 10, laneMaxZ: 20, roadCenterZ: 25 };
105|  const base = { x: 1200, z: 15 };
106|  const { steps, cars } = podiumLayout([
107|    { id: 2, name: 'Bob', t: 12050, dnf: false, pen: 0 },
108|    { id: 1, name: 'Alice', t: 12100, dnf: false, pen: 2000 },
109|    { id: 3, name: 'Carol', t: 13900, dnf: false },
110|    { id: 4, name: 'Dan', t: null, dnf: true },
111|  ], base, road);
112|  assert.deepEqual(steps, [
113|    { place: 1, x: 1206, z: 8, w: 2.2, d: 2.2, h: 0.4 },
114|    { place: 2, x: 1206, z: 5.6, w: 2.2, d: 2.2, h: 0.3 },
115|    { place: 3, x: 1206, z: 3.2, w: 2.2, d: 2.2, h: 0.2 },
116|  ]);
117|  for (const s of steps) assert.ok(s.z < road.laneMinZ, 'steps never block the racing lane');
118|  assert.deepEqual(cars, [
119|    { id: 2, name: 'Bob', x: 1206, z: 8, heading: Math.PI / 2, place: 1, dnf: false },
120|    { id: 1, name: 'Alice', x: 1206, z: 5.6, heading: Math.PI / 2, place: 2, dnf: false },
121|    { id: 3, name: 'Carol', x: 1206, z: 3.2, heading: Math.PI / 2, place: 3, dnf: false },
122|    { id: 4, name: 'Dan', x: 1206, z: 1, heading: Math.PI / 2, place: null, dnf: true },
123|  ]);
124|});
125|
126|test('podium: fewer racers still give three steps, cars only for finishers', () => {
127|  // laneMinZ/laneMaxZ swapped in the input: the NORTH edge is still min(z0, z1).
128|  const { steps, cars } = podiumLayout([
129|    { id: 7, name: 'A', t: 1000, dnf: false },
130|    { id: 8, name: 'B', t: 2000, dnf: false },
131|  ], { x: 0, z: 0 }, { laneMinZ: -1, laneMaxZ: -5, roadCenterZ: -3 });
132|  assert.equal(steps.length, 3, 'the podium always stands with three steps');
133|  assert.deepEqual(steps.map((s) => s.z), [-7, -9.4, -11.8], 'place 1 sits nearest the lane edge (min of the two)');
134|  assert.deepEqual(cars, [
135|    { id: 7, name: 'A', x: 6, z: -7, heading: Math.PI / 2, place: 1, dnf: false },
136|    { id: 8, name: 'B', x: 6, z: -9.4, heading: Math.PI / 2, place: 2, dnf: false },
137|  ]);
138|  assert.deepEqual(steps.map((s) => s.h), [0.4, 0.3, 0.2], 'place 1 is the highest step');
139|});", "total_lines": 139, "file_size": 6827, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|// Phase 3: the remote-car interpolation buffer (src/net/remoteCar.js) —
2|// pure unit coverage plus one end-to-end test fed by fakeNet posRelay frames.
3|import { test } from 'node:test';
4|import assert from 'node:assert/strict';
5|import { FakeNet, FakeServer } from '../server/fakeNet.js';
6|import { createRaceState } from '../server/raceState.js';
7|import { encode } from '../server/protocol.js';
8|import { createNetClient } from '../src/net/client.js';
9|import { createInterp } from '../src/net/remoteCar.js';
10|
11|test('sample is null before any snapshot', () => {
12|  assert.equal(createInterp().sample(1000), null);
13|});
14|
15|test('sampling before the first snapshot returns the earliest snapshot', () => {
16|  const i = createInterp();
17|  i.push({ t: 500, x: 1, z: 2, h: 0.5, s: 4 });
18|  assert.deepEqual(i.sample(0), { x: 1, z: 2, h: 0.5, s: 4 });
19|  assert.deepEqual(i.sample(400), { x: 1, z: 2, h: 0.5, s: 4 }, 'default 100 ms delay still misses t=500');
20|  assert.deepEqual(i.sample(600), { x: 1, z: 2, h: 0.5, s: 4 }, 'renderT hits t exactly: the snapshot itself');
21|});
22|
23|test('position, speed and heading interpolate linearly between snapshots', () => {
24|  const i = createInterp();
25|  i.push({ t: 0, x: 0, z: 0, h: 0, s: 0 });
26|  i.push({ t: 100, x: 10, z: -4, h: 1, s: 2 });
27|  assert.deepEqual(i.sample(150), { x: 5, z: -2, h: 0.5, s: 1 }, 'halfway between, at default 100 ms delay');
28|  assert.deepEqual(i.sample(200), { x: 10, z: -4, h: 1, s: 2 }, 'exactly the second snapshot');
29|});
30|
31|test('heading follows the shortest arc, normalized to −π..π', () => {
32|  // 2.8 rad → −3.0 rad wraps through +π (0.483 rad), not backwards via north.
33|  const wrap = createInterp();
34|  wrap.push({ t: 0, x: 0, z: 0, h: 2.8, s: 1 });
35|  wrap.push({ t: 100, x: 0, z: 0, h: -3.0, s: 1 });
36|  const mid = wrap.sample(150).h;
37|  assert.ok(Math.abs(mid - 3.041592653589793) < 1e-9, 'midway through the short +π crossing');
38|  assert.ok(mid > 0, 'not the long way round');
39|  // Stepping past +π re-emerges on the −π branch.
40|  const over = createInterp();
41|  over.push({ t: 0, x: 0, z: 0, h: 3.1, s: 1 });
42|  over.push({ t: 100, x: 0, z: 0, h: 3.2, s: 1 });
43|  const h = over.sample(150).h;
44|  assert.ok(Math.abs(h - (3.15 - 2 * Math.PI)) < 1e-9, 'output normalized: 3.15 rad reads −3.133 rad');
45|});
46|
47|test('clamps at the newest snapshot — no extrapolation', () => {
48|  const i = createInterp();
49|  i.push({ t: 0, x: 0, z: 0, h: 0, s: 0 });
50|  i.push({ t: 100, x: 10, z: 0, h: 0, s: 2 });
51|  assert.deepEqual(i.sample(10 ** 6), { x: 10, z: 0, h: 0, s: 2 }, 'long past the buffer: hold the newest');
52|  assert.equal(i.sample(200).x, 10, 'exactly at the newest t: settled, not extrapolated');
53|});
54|
55|test('out-of-order pushes are ignored — never teleports backwards', () => {
56|  const i = createInterp();
57|  i.push({ t: 100, x: 10, z: 0, h: 0, s: 0 });
58|  i.push({ t: 50, x: 5, z: 0, h: 0, s: 0 }); // too old: ignored
59|  i.push({ t: 100, x: 7, z: 0, h: 0, s: 0 }); // equals the newest: ignored too
60|  assert.equal(i.sample(0).x, 10, 'earliest snapshot is still t=100 (the 50 ms one never landed)');
61|  i.push({ t: 200, x: 20, z: 0, h: 0, s: 1 });
62|  assert.equal(i.sample(250).x, 15, 'a fresh newest is accepted and interpolates (renderT=150: halfway)');
63|});
64|
65|// End-to-end: another player streams at 10 Hz over fakeNet while the winner
66|// side samples; the stream must read continuous, time-monotonic and clamped.
67|test('interpolation fed by fakeNet posRelay is continuous, monotonic and clamped', () => {
68|  const net = new FakeNet();
69|  const server = new FakeServer(net);
70|  const race = createRaceState({
71|    seed: 7,
72|    now: () => net.now,
73|    send: (conn, type, data) => conn.send(encode(type, data)),
74|    close: (conn, code, reason) => conn.close(code, reason),
75|    schedule: (delayMs, fn) => net.schedule(delayMs, fn),
76|  });
77|  server.onConnect = (conn) => {
78|    race.connect(conn);
79|    conn.onMessage = (text) => race.onMessage(conn, text);
80|    conn.onClose = () => race.disconnect(conn);
81|  };
82|  const watcherLog = [];
83|  const mk = (name, peerPos) => {
84|    const conn = server.connect();
85|    return createNetClient({
86|      conn, name, now: () => net.now, every: (ms, fn) => net.schedule(ms, fn),
87|      on: { peerPos: (st) => peerPos(st) },
88|    });
89|  };
90|  const jumper = mk('B', () => {});
91|  const watcher = mk('A', (st) => watcherLog.push(st));
92|  net.advance(0);
93|  jumper.startRace();
94|  net.advance(3000); // racing
95|  for (let k = 0; k <= 5; k++) net.schedule(k * 100, () => jumper.sendPos({ x: 10 * k, z: 0, h: 0, s: k }));
96|  net.advance(600);
97|  // The relay hook plays the buffered feed, exactly like the integration wiring.
98|  const interp = createInterp();
99|  for (const st of watcherLog) interp.push({ t: st.t, x: st.x, z: st.z, h: st.h, s: st.s });
100|
101|  let prev = interp.sample(150);
102|  for (let r = 160; r <= 600; r += 10) {
103|    const st = interp.sample(r);
104|    assert.ok(st.x - prev.x >= -1e-9, `position never moves backwards at r=${r}`);
105|    assert.ok(st.x - prev.x <= 1 + 1e-9, `no jump at r=${r} (10 m per 100 ms stream)`);
106|    assert.ok(Math.abs(st.s - prev.s) <= 0.1 + 1e-9, `speed just as smooth at r=${r}`);
107|    prev = st;
108|  }
109|  assert.equal(interp.sample(1e6).x, 50, 'clamped: holds the newest snapshot forever');
110|  let before = interp.sample(100); // before the first snapshot (t=0 at delay 100)
111|  assert.equal(before.x, 0, 'renders the earliest snapshot before play begins');
112|});", "total_lines": 112, "file_size": 5360, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|// Phase 2: master-clock maths (src/net/clock.js) — pure, given known rtt/offset.
2|import { test } from 'node:test';
3|import assert from 'node:assert/strict';
4|import { createClock } from '../src/net/clock.js';
5|
6|test('offset math for a known rtt and clock difference', () => {
7|  const clock = createClock(8);
8|  assert.equal(clock.synced(), false);
9|  assert.equal(clock.offset(), null);
10|  assert.equal(clock.serverNow(0), null, 'unsynced → no server time');
11|  // Server runs 500 ms ahead. Local sends at 0; 50 ms each way, so the server
12|  // stamps its clock at 550 (real 50 + skew 500) and the reply lands at 100.
13|  clock.onPong(0, 550, 100);
14|  assert.equal(clock.synced(), true);
15|  assert.equal(clock.serverNow(100), 600, 'local 100 ↔ server 600 (skew 500)');
16|  assert.equal(clock.serverNow(1100), 1600, 'relative reading stays stable');
17|});
18|
19|test('min-rtt over N samples beats noisy ones', () => {
20|  const clock = createClock(8);
21|  // Same server (skew +500), but the request leg queues extra milliseconds Q
22|  // (asymmetric wire): the pong is stamped late, so estimate error = Q / 2.
23|  // Send at local 100, base legs 10 ms each: server stamps 610 + Q, arrives at 120 + Q.
24|  const pong = (q) => clock.onPong(100, 610 + q, 120 + q);
25|  pong(500); // heavy queueing: estimate 750, badly off
26|  pong(400);
27|  pong(300);
28|  pong(0); // clean round trip: exact
