{"content": "1|// Phase 2: track invariants per seed — 200 m, on road, clear corridor, grid
2|// slots non-overlapping and facing east, idempotent for equal seeds.
3|import { test } from 'node:test';
4|import assert from 'node:assert/strict';
5|import { generateCity, streetAt } from '../src/world/cityGen.js';
6|import { buildTrack, TRACK_LENGTH } from '../src/net/track.js';
7|import { TAXI } from '../src/vehicle/carPhysics.js';
8|import { pushOut } from '../src/vehicle/collision.js';
9|
10|const SEEDS = [7, 42, 1989, 2024, 123456];
11|
12|test('rejects impossible player counts and rejects a truncated city', () => {
13|  const city = generateCity({ seed: 42 });
14|  assert.throws(() => buildTrack(city, 1), RangeError);
15|  assert.throws(() => buildTrack(city, 5), RangeError);
16|  assert.throws(() => buildTrack(city, 2.5), RangeError);
17|});
18|
19|for (const seed of SEEDS) {
20|  for (const players of [2, 3, 4]) {
21|    test(`seed ${seed}, ${players} players: track invariants hold`, () => {
22|      const city = generateCity({ seed });
23|      const track = buildTrack(city, players);
24|
25|      // 200 m exactly, straight east on the boulevard, east of the gate.
26|      assert.equal(track.finish.x - track.start.x, TRACK_LENGTH);
27|      const gate = city.landmarks.find((l) => l.kind === 'gate');
28|      assert.ok(track.start.x > gate.x, 'starts east of the gate');
29|      assert.equal(track.grid.length, players);
30|      for (const slot of track.grid) {
31|        assert.equal(slot.heading, Math.PI / 2, 'facing east');
32|        assert.equal(slot.x, track.start.x, 'grid on one line');
33|        assert.equal(streetAt(city, slot.x, slot.z), 'Unter den Linden', 'grid is on the boulevard, not a junction');
34|        assert.ok(slot.z > track.finish.z0 && slot.z < track.finish.z1, 'slot inside the racing lane');
35|      }
36|      assert.ok(streetAt(city, track.finish.x, (track.finish.z0 + track.finish.z1) / 2).startsWith('Unter den Linden'),
37|        'finish line rests on the boulevard (at a crossing at worst)');
38|
39|      // Place-only collision check: every seat clears the whole city, front and
40|      // rear circle.
41|      for (const slot of track.grid)
42|        for (const off of [TAXI.collisionOffset, -TAXI.collisionOffset])
43|          assert.equal(pushOut(slot.x + off, slot.z, TAXI.collisionRadius, city.colliders), null, 'slot collides');
44|
45|      // No two seats overlap (they are two taxi bodies, worst case sideways).
46|      for (let a = 0; a < track.grid.length; a++)
47|        for (let b = a + 1; b < track.grid.length; b++)
48|          assert.ok(Math.abs(track.grid[a].z - track.grid[b].z) >= TAXI.trackWidth * 1.4, 'slots overlap');
49|
50|      // Corridor: no collider touches the driving band, start to finish.
51|      const c = track.corridor;
52|      const overlapping = city.colliders.filter(
53|        (x) => x.type === 'box' && x.x0 < c.x1 && x.x1 > c.x0 && x.z0 < c.z1 && x.z1 > c.z0);
54|      assert.deepEqual(overlapping, [], `colliders in corridor: ${JSON.stringify(overlapping)}`);
55|
56|      // The ampel stands near the line, ahead of the grid.
57|      assert.ok(track.ampel.x > track.start.x && track.ampel.x - track.start.x < 30);
58|    });
59|  }
60|}
61|
62|test('identical seed → identical track, every player count', () => {
63|  for (const seed of SEEDS) {
64|    for (const players of [2, 3, 4]) {
65|      const a = buildTrack(generateCity({ seed }), players);
66|      const b = buildTrack(generateCity({ seed }), players);
67|      assert.deepEqual(a, b);
68|    }
69|  }
70|});", "total_lines": 70, "file_size": 3387, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

